(()=>{const nav=document.getElementById('mobile-nav'),toggle=document.querySelector('.mobile-toggle'),dialog=document.getElementById('reservation-dialog');let focus;function closeNav(){nav.hidden=true;toggle.setAttribute('aria-expanded','false')}toggle.addEventListener('click',()=>{nav.hidden=!nav.hidden;toggle.setAttribute('aria-expanded',String(!nav.hidden))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeNav));document.querySelectorAll('[data-reserve]').forEach(button=>button.addEventListener('click',()=>{closeNav();focus=button;dialog.showModal();document.body.style.overflow='hidden'}));dialog.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';focus?.focus()});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeNav()})})();